48: /** A test base for testing {@link TypeSerializer} upgrades. */
49: @TestInstance(TestInstance.Lifecycle.PER_CLASS)
50: public abstract class TypeSerializerUpgradeTestBase<PreviousElementT, UpgradedElementT>
