585:         DataOutputSerializer out = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
586:         writeSerializerSnapshotCurrentFormat(out, serializer);
587: 
588:         DataInputDeserializer in = new DataInputDeserializer(out.wrapAsByteBuffer());
589:         return readSerializerSnapshotCurrentFormat(
590:                 in, Thread.currentThread().getContextClassLoader());
