78:     /**
79:      * Setup code for a {@link TestSpecification}. This creates the serializer before upgrade and
80:      * test data, that will be written by the created pre-upgrade {@link TypeSerializer}.
81:      */
82:     public interface PreUpgradeSetup<PreviousElementT> {
83: 
84:         /** Creates a pre-upgrade {@link TypeSerializer}. */
85:         TypeSerializer<PreviousElementT> createPriorSerializer();
86: 
