92:      * Verification code for a {@link TestSpecification}. This creates the "upgraded" {@link
93:      * TypeSerializer} and provides matchers for comparing the deserialized test data and for the
94:      * {@link TypeSerializerSchemaCompatibility}.
95:      */
96:     public interface UpgradeVerifier<UpgradedElementT> {
97: 
98:         /** Creates a post-upgrade {@link TypeSerializer}. */
99:         TypeSerializer<UpgradedElementT> createUpgradedSerializer();
100: 
101:         /** Returns a {@link Matcher} for asserting the deserialized test data. */
102:         Matcher<UpgradedElementT> testDataCondition();
103: 
