200:     public static class TestSpecification<PreviousElementT, UpgradedElementT> {
201:         private final String name;
202:         private final FlinkVersion flinkVersion;
203:         private final ClassLoaderSafePreUpgradeSetup<PreviousElementT> setup;
204:         private final ClassLoaderSafeUpgradeVerifier<UpgradedElementT> verifier;
205: 
206:         public TestSpecification(
207:                 String name,
208:                 FlinkVersion flinkVersion,
209:                 Class<? extends PreUpgradeSetup<PreviousElementT>> setupClass,
210:                 Class<? extends UpgradeVerifier<UpgradedElementT>> verifierClass)
211:                 throws Exception {
212:             this.name = checkNotNull(name);
213:             this.flinkVersion = checkNotNull(flinkVersion);
214:             this.setup = new ClassLoaderSafePreUpgradeSetup<>(setupClass);
215:             this.verifier = new ClassLoaderSafeUpgradeVerifier<>(verifierClass);
216:         }
