235:     @ParameterizedSnapshotsGenerator("createTestSpecifications")
236:     public void generateTestSetupFiles(
237:             TestSpecification<PreviousElementT, UpgradedElementT> testSpecification)
238:             throws Exception {
239:         Files.createDirectories(getSerializerSnapshotFilePath(testSpecification).getParent());
240: 
241:         try (ThreadContextClassLoader ignored =
242:                 new ThreadContextClassLoader(testSpecification.setup.setupClassloader)) {
243:             TypeSerializer<PreviousElementT> priorSerializer =
244:                     testSpecification.setup.createPriorSerializer();
245: 
246:             // first, use the serializer to write test data
247:             // NOTE: it is important that we write test data first, because some serializers'
248:             // configuration
249:             //       mutates only after being used for serialization (e.g. dynamic type
250:             // registrations for Pojo / Kryo)
251:             DataOutputSerializer testDataOut = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
252:             priorSerializer.serialize(testSpecification.setup.createTestData(), testDataOut);
253:             writeContentsTo(
254:                     getGenerateDataFilePath(testSpecification), testDataOut.getCopyOfBuffer());
255: 
256:             // ... then write the serializer snapshot
257:             DataOutputSerializer serializerSnapshotOut =
258:                     new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
259:             writeSerializerSnapshot(
260:                     serializerSnapshotOut, priorSerializer, testSpecification.flinkVersion);
261:             writeContentsTo(
262:                     getGenerateSerializerSnapshotFilePath(testSpecification),
263:                     serializerSnapshotOut.getCopyOfBuffer());
264:         }
265:     }
