567:     private static <T> DataInputView readAndThenWriteData(
568:             DataInputView originalDataInput,
569:             TypeSerializer<T> readSerializer,
570:             TypeSerializer<T> writeSerializer,
571:             Matcher<T> testDataMatcher)
572:             throws IOException {
573: 
574:         T data = readSerializer.deserialize(originalDataInput);
575:         assertThat(data).is(HamcrestCondition.matching(testDataMatcher));
576: 
577:         DataOutputSerializer out = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
578:         writeSerializer.serialize(data, out);
579:         return new DataInputDeserializer(out.wrapAsByteBuffer());
580:     }
