533:     private static <T> void writeSerializerSnapshot(
534:             DataOutputView out, TypeSerializer<T> serializer, FlinkVersion flinkVersion)
535:             throws IOException {
536: 
537:         if (flinkVersion.isNewerVersionThan(FlinkVersion.v1_6)) {
538:             writeSerializerSnapshotCurrentFormat(out, serializer);
539:         } else {
540:             throw new UnsupportedOperationException(
541:                     "There should be no longer a need to support/use this path since Flink 1.17");
542:         }
