516:     private static void writeContentsTo(Path path, byte[] bytes) {
517:         try {
518:             Files.write(path, bytes);
519:         } catch (IOException e) {
520:             throw new RuntimeException("Failed to write to " + path, e);
521:         }
522:     }
523: 
524:     private static DataInputView contentsOf(Path path) {
525:         try {
526:             byte[] bytes = Files.readAllBytes(path);
527:             return new DataInputDeserializer(bytes);
528:         } catch (IOException e) {
529:             throw new RuntimeException("Failed to read contents of " + path, e);
530:         }
531:     }
