545:     private static <T> void writeSerializerSnapshotCurrentFormat(
546:             DataOutputView out, TypeSerializer<T> serializer) throws IOException {
547: 
548:         TypeSerializerSnapshotSerializationUtil.writeSerializerSnapshot(
549:                 out, serializer.snapshotConfiguration());
550:     }
