552:     private static <T> TypeSerializerSnapshot<T> readSerializerSnapshot(
553:             DataInputView in, FlinkVersion flinkVersion) throws IOException {
554: 
555:         ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
556:         checkState(flinkVersion.isNewerVersionThan(FlinkVersion.v1_6));
557:         return readSerializerSnapshotCurrentFormat(in, classLoader);
558:     }
559: 
560:     private static <T> TypeSerializerSnapshot<T> readSerializerSnapshotCurrentFormat(
561:             DataInputView in, ClassLoader userCodeClassLoader) throws IOException {
562: 
563:         return TypeSerializerSnapshotSerializationUtil.readSerializerSnapshot(
564:                 in, userCodeClassLoader);
565:     }
566: 
567:     private static <T> DataInputView readAndThenWriteData(
568:             DataInputView originalDataInput,
569:             TypeSerializer<T> readSerializer,
570:             TypeSerializer<T> writeSerializer,
571:             Matcher<T> testDataMatcher)
572:             throws IOException {
573: 
574:         T data = readSerializer.deserialize(originalDataInput);
575:         assertThat(data).is(HamcrestCondition.matching(testDataMatcher));
576: 
577:         DataOutputSerializer out = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
578:         writeSerializer.serialize(data, out);
579:         return new DataInputDeserializer(out.wrapAsByteBuffer());
580:     }
581: 
582:     private static <T> TypeSerializerSnapshot<T> writeAndThenReadSerializerSnapshot(
583:             TypeSerializer<T> serializer) throws IOException {
584: 
585:         DataOutputSerializer out = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
586:         writeSerializerSnapshotCurrentFormat(out, serializer);
587: 
588:         DataInputDeserializer in = new DataInputDeserializer(out.wrapAsByteBuffer());
589:         return readSerializerSnapshotCurrentFormat(
590:                 in, Thread.currentThread().getContextClassLoader());
591:     }
592: }
