201:         private final String name;
202:         private final FlinkVersion flinkVersion;
203:         private final ClassLoaderSafePreUpgradeSetup<PreviousElementT> setup;
204:         private final ClassLoaderSafeUpgradeVerifier<UpgradedElementT> verifier;
205: 
206:         public TestSpecification(
207:                 String name,
208:                 FlinkVersion flinkVersion,
