242:                 new ThreadContextClassLoader(testSpecification.setup.setupClassloader)) {
243:             TypeSerializer<PreviousElementT> priorSerializer =
244:                     testSpecification.setup.createPriorSerializer();
245: 
246:             // first, use the serializer to write test data
247:             // NOTE: it is important that we write test data first, because some serializers'
248:             // configuration
249:             //       mutates only after being used for serialization (e.g. dynamic type
250:             // registrations for Pojo / Kryo)
251:             DataOutputSerializer testDataOut = new DataOutputSerializer(INITIAL_OUTPUT_BUFFER_SIZE);
252:             priorSerializer.serialize(testSpecification.setup.createTestData(), testDataOut);
253:             writeContentsTo(
254:                     getGenerateDataFilePath(testSpecification), testDataOut.getCopyOfBuffer());
