425:     /**
426:      * Asserts that a given {@link TypeSerializer} is valid, given a {@link DataInputView} of
427:      * serialized data.
428:      *
429:      * <p>A serializer is valid, iff:
430:      *
431:      * <ul>
432:      *   <li>1. The serializer can read and then write again the given serialized data.
433:      *   <li>2. The serializer can produce a serializer snapshot which can be written and then read
434:      *       back again.
435:      *   <li>3. The serializer's produced snapshot is capable of creating a restore serializer.
436:      *   <li>4. The restore serializer created from the serializer snapshot can read and then write
437:      *       again data written by step 1. Given that the serializer is not a restore serializer
438:      *       already.
439:      * </ul>
440:      */
441:     private static <T> void assertSerializerIsValid(
442:             TypeSerializer<T> serializer, DataInputView dataInput, Matcher<T> testDataMatcher)
443:             throws Exception {
444: 
445:         DataInputView serializedData =
446:                 readAndThenWriteData(dataInput, serializer, serializer, testDataMatcher);
447:         TypeSerializerSnapshot<T> snapshot = writeAndThenReadSerializerSnapshot(serializer);
448:         TypeSerializer<T> restoreSerializer = snapshot.restoreSerializer();
449:         serializedData =
450:                 readAndThenWriteData(
451:                         serializedData, restoreSerializer, restoreSerializer, testDataMatcher);
452: 
453:         TypeSerializer<T> duplicateSerializer = snapshot.restoreSerializer().duplicate();
454:         readAndThenWriteData(
455:                 serializedData, duplicateSerializer, duplicateSerializer, testDataMatcher);
456:     }
